import json
import os

def save_game(state):
    with open("save.json", "w") as f:
        json.dump(state, f)

def load_game():
    if not os.path.exists("save.json"):
        return None
    with open("save.json") as f:
        return json.load(f)

print(load_game())
save_game({"hp": 50, "place": "lighthouse"})
print(load_game())
